@Bean
@Scope("singleton")
public Customer customer() {
    return new Customer();
}

@Bean
@Scope(value = ConfigurableBeanFactory.SCOPE_SINGLETON)
public Customer customer() {
    return new Customer();
}

@Bean
@Scope("prototype")
public Customer customer() {
    return new Customer();
}

@Bean
@Scope(value = ConfigurableBeanFactory.SCOPE_PROTOTYPE)
public Customer customer() {
    return new Customer();
}

@Component
@Scope("singleton") // or "prototype"
public class Customer {
    public Customer() {
        System.out.println("Customer Bean Created");
    }
}

public class App {
    public static void main(String[] args) {
        AnnotationConfigApplicationContext context = new AnnotationConfigApplicationContext(AppConfig.class);

        Customer c1 = context.getBean(Customer.class);
        Customer c2 = context.getBean(Customer.class);

        System.out.println(c1 == c2 ? "Same Instance" : "Different Instances");

        context.close();
    }
}

